<script>document.querySelectorAll('[data-price]').forEach(input=>input.addEventListener('input',updateTotal));function updateTotal(){let cents=0;document.querySelectorAll('[data-price]').forEach(input=>{const quantity=Number(input.value),minimum=Number(input.dataset.minimum);input.setCustomValidity(quantity>0&&quantity<minimum?'Минимальный заказ — '+minimum+' шт.':'');if(Number.isSafeInteger(quantity)&&quantity>0)cents+=quantity*Number(input.dataset.price)});document.getElementById('live-total').textContent=(Math.floor(cents/100)).toLocaleString('ru-RU')+','+String(cents%100).padStart(2,'0')+' ₽'}updateTotal()</script>
